/* Generated by codegen/emit_frames.py from registry/parts.toml - DO NOT EDIT.
 *
 * World-frame table for bsk_link's generic frame consumer (REG): one row per
 * registered part whose frames cross the airgap onto the bus. To onboard a
 * part: land its registry row, re-run codegen/emit_frames.py, rebuild - no C
 * edits. bsk_link resolves every container by name against the linked EDS
 * database at startup and disables any row whose size disagrees with this
 * table (naming the part on the event bus), so registry, schema, and binary
 * are mutually checked at boot, not just at commit time.
 */
#ifndef ORRERY_FRAMES_H
#define ORRERY_FRAMES_H

#include "cfe.h"
#include "orrery_msgids.h"
#define BSK_LINK_FRAME_ROWS 3
#define BSK_LINK_FRAME_MAX_PAYLOAD 128

/* Fit handshake (OB): the digest of this table's SEMANTICS (row order,
 * topics, containers, sizes, MsgIds, EVS ids - not comments). The world
 * recomputes it from the registry it loaded and ships it in every
 * FitManifest; a mismatch means one side is stale, which no size check
 * can see (a stale binary is perfectly self-consistent). Rebuild:
 * uv run python -m codegen.emit_frames, then cfs_mission/build.sh. */
#define BSK_LINK_FIT_REGISTRY_HASH 0xf0b0bfb6u

typedef struct
{
    const char *Topic;     /* ZMQ multipart frame 1                                */
    const char *Container; /* EDS type name, resolved against the linked database    */
    uint16      Mid;       /* SB MsgId (generated orrery_part_msgids.h)              */
    uint16      Size;      /* payload bytes; EDS must agree at startup or row off    */
    uint16      EvsId;     /* first/every-N EVS event identity                       */
    const char *Label;     /* operator text for the event line                       */
} BskLink_WorldFrameDef_t;

static const BskLink_WorldFrameDef_t BskLink_WorldFrames[BSK_LINK_FRAME_ROWS] = {
    /* name: gnss - GNSS receiver (orbital knowledge, KN/KN2) */
    { "NAVSTATE", "BSK_LINK/NavState", BSK_LINK_NAV_STATE_TLM_MID,
      /* evs */ 64, 15 /* BSK_LINK_NAV_INF_EID */,
      "GNSS fix" },
    /* name: onboard - onboard knowledge bundle (P4b; wheels/ST/CSS/mag in one frame) */
    { "ONBOARD", "BSK_LINK/OnboardState", BSK_LINK_ONBOARD_STATE_TLM_MID,
      /* evs */ 128, 14 /* BSK_LINK_ONBOARD_INF_EID */,
      "onboard state" },
    /* name: attitude - star tracker (attitude knowledge, REG exit) */
    { "ATTSTATE", "BSK_LINK/AttitudeState", BSK_LINK_ATTITUDE_STATE_TLM_MID,
      /* evs */ 48, 16 /* BSK_LINK_ATTSTATE_INF_EID */,
      "ST attitude" },
};

#endif /* ORRERY_FRAMES_H */
